    const headers=[...table.querySelectorAll('thead th')];headers.forEach((cell,index)=>{cell.style.position='sticky';cell.style.top='0';cell.style.zIndex='20';cell.style.background='#fbbf24';cell.style.boxShadow='0 1px 0 #b45309';if(index===0){cell.style.left='0';cell.style.zIndex='40'}if(index===1){cell.style.left='250px';cell.style.zIndex='40'}});
    table.querySelectorAll('[data-spo-row]:not([data-spo-system])').forEach(row=>{[[row.querySelector('[data-spo-event]')?.closest('td'),'0','250px'],[row.querySelector('[data-spo-baseline]')?.closest('td'),'250px','60px']].forEach(([cell,left,width])=>{if(cell){cell.style.position='sticky';cell.style.left=left;cell.style.width=width;cell.style.minWidth=width;cell.style.maxWidth=width;cell.style.zIndex='15';cell.style.background='#fff';cell.style.boxShadow='1px 0 0 #cbd5e1'}})});
